mapper.select:
SELECT
n.notify_id, n.title, n.content, n.type, n.course_id,
n.publisher_id, n.publish_time,
nr.is_read, nr.read_time,
-- 关联查询发布者姓名（可选）
(SELECT sys_user.username FROM sys_user WHERE user_id = n.publisher_id) as publisher_name
FROM notification n
INNER JOIN notification_receiver nr ON n.notify_id = nr.notification_id
WHERE nr.receiver_id = #{userId}



    AND n.course_id = #{courseId}


    AND n.type = #{type}


    AND nr.is_read = #{isRead}


ORDER BY n.publish_time DESC
LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE notification_receiver
SET is_read = 1, read_time = NOW()
WHERE receiver_id = #{userId} AND notification_id = #{notifyId}

UPDATE notification_receiver nr
    INNER JOIN notification n ON nr.notification_id = n.notify_id
SET nr.is_read = 1, nr.read_time = NOW()
WHERE nr.receiver_id = #{userId}
  AND n.course_id = #{courseId}
  AND nr.is_read = 0
